#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

using LL = long long;
using i128 = __int128_t;

i128 power(LL base, LL exponent) {
    i128 result = 1;
    while (exponent-- > 0) {
        result *= base;
    }
    return result;
}

LL digitSum(LL value) {
    LL sum = 0;
    while (value > 0) {
        sum += value % 10;
        value /= 10;
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    LL a, b, c;
    cin >> a >> b >> c;

    vector<LL> solutions;

    for (LL s = 1; s <= 81; ++s) {
        i128 candidate = static_cast<i128>(b) * power(s, a) + c;

        if (candidate > 0 && candidate < 1000000000LL) {
            LL x = static_cast<LL>(candidate);
            if (digitSum(x) == s) {
                solutions.push_back(x);
            }
        }
    }

    sort(solutions.begin(), solutions.end());
    solutions.erase(unique(solutions.begin(), solutions.end()), solutions.end());

    cout << solutions.size() << '\n';
    for (LL x : solutions) {
        cout << x << ' ';
    }

    return 0;
}

